-- 主键查询：一次 B+ 树
select * from emp where id = 1;
-- 二级索引查询：先查 name 索引拿到 id，再回表
select * from emp where name = '张三';

create index idx_dept_hire on emp(dept_id, hire_date);
-- 覆盖索引：Extra 显示 Using index
explain select dept_id, hire_date from emp where dept_id = 1;

-- 能用到索引
select * from emp where dept_id = 1 and hire_date > '2020-01-01';
-- 用不到（跳过了最左列）
select * from emp where hire_date > '2020-01-01';

-- 失效：字段上用了函数
select * from emp where year(hire_date) = 2020;
-- 改写：范围条件
select * from emp where hire_date >= '2020-01-01' and hire_date < '2021-01-01';

-- 排他锁
select * from emp where id = 1 for update;
-- 共享锁
select * from emp where id = 1 lock in share mode;

-- 乐观锁：带上 version 条件
update emp set salary = salary + 100, version = version + 1
where id = 1 and version = 3;

create table emp (
  id bigint primary key auto_increment,
  name varchar(20) not null
) engine = InnoDB default charset = utf8mb4;

set global slow_query_log = on;
set global long_query_time = 1;
-- 查看当前慢查询条数
show global status like 'Slow_queries';

-- 延迟关联
select e.* from emp e join (select id from emp order by id limit 100000, 10) t on e.id = t.id;
-- 游标分页（推荐）
select * from emp where id > 100000 order by id limit 10;

